#!/usr/bin/env bash
# Sign outside Gradle: android/ is regenerated by Capacitor on every CI run.
set -euo pipefail

if [[ $# -ne 2 ]]; then
  echo "Usage: $0 unsigned.apk signed.apk" >&2
  exit 1
fi
for key in ANDROID_KEYSTORE_BASE64 ANDROID_KEYSTORE_PASSWORD ANDROID_KEY_ALIAS ANDROID_KEY_PASSWORD; do
  if [[ -z "${!key:-}" ]]; then
    echo "Missing signing secret: $key" >&2
    exit 1
  fi
done
sdk_root="${ANDROID_SDK_ROOT:-${ANDROID_HOME:-}}"
if [[ -z "$sdk_root" || ! -d "$sdk_root/build-tools" ]]; then
  echo "Android SDK build-tools not found; set ANDROID_SDK_ROOT or ANDROID_HOME" >&2
  exit 1
fi
# Use the newest installed stable build-tools (not a preview).
build_tools="$(find "$sdk_root/build-tools" -mindepth 1 -maxdepth 1 -type d \
  | grep -E '/[0-9]+\.[0-9]+\.[0-9]+$' | sort -V | tail -n 1)"
if [[ ! -x "$build_tools/zipalign" || ! -x "$build_tools/apksigner" ]]; then
  echo "Android zipalign/apksigner not found" >&2
  exit 1
fi

umask 077
tmp="$(mktemp -d)"
trap 'rm -rf "$tmp"' EXIT
printf '%s' "$ANDROID_KEYSTORE_BASE64" | base64 --decode > "$tmp/release.jks"
mkdir -p "$(dirname "$2")"
# Align before signing; modifying a signed APK invalidates its signature.
"$build_tools/zipalign" -P 16 -f 4 "$1" "$tmp/aligned.apk"
"$build_tools/apksigner" sign \
  --ks "$tmp/release.jks" \
  --ks-key-alias "$ANDROID_KEY_ALIAS" \
  --ks-pass env:ANDROID_KEYSTORE_PASSWORD \
  --key-pass env:ANDROID_KEY_PASSWORD \
  --out "$tmp/signed.apk" "$tmp/aligned.apk"
"$build_tools/apksigner" verify --verbose --print-certs "$tmp/signed.apk"
"$build_tools/zipalign" -c -P 16 4 "$tmp/signed.apk"
# Only expose an artifact after both checks succeed. No private key is uploaded.
cp "$tmp/signed.apk" "$2"
